CREATE TABLE `tb_blog` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `shop_id` bigint DEFAULT NULL COMMENT '商户id，可为空（纯内容笔记）',
  `user_id` bigint unsigned NOT NULL COMMENT '用户id',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `images` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '探店的照片，最多9张，多张以","隔开',
  `content` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '探店的文字描述',
  `liked` int unsigned DEFAULT '0' COMMENT '点赞数量',
  `comments` int unsigned NOT NULL DEFAULT '0' COMMENT '评论数量',
  `view_count` int unsigned NOT NULL DEFAULT '0' COMMENT '浏览量',
  `collected` int unsigned NOT NULL DEFAULT '0' COMMENT '收藏数量',
  `score` tinyint unsigned DEFAULT NULL COMMENT '探店评分 1~5 分乘 10 保存',
  `topic_id` bigint unsigned DEFAULT NULL COMMENT '话题id',
  `location` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '定位/商圈',
  `status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '状态 0:正常 1:作者隐藏 2:违规下架',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_blog_user` (`user_id`),
  KEY `idx_blog_shop` (`shop_id`),
  KEY `idx_blog_topic` (`topic_id`),
  KEY `idx_blog_status_time` (`status`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=COMPACT;
