INSERT INTO `tb_blog` VALUES (4,4,2,'无尽浪漫的夜晚丨在万花丛中摇晃着红酒杯🍷品战斧牛排🥩','/imgs/blogs/7/14/4771fefb-1a87-4252-816c-9f7ec41ffa4a.jpg,/imgs/blogs/4/10/2f07e3c9-ddce-482d-9ea7-c21450f8d7cd.jpg,/imgs/blogs/2/6/b0756279-65da-4f2d-b62a-33f74b06454a.jpg,/imgs/blogs/10/7/7e97f47d-eb49-4dc9-a583-95faa7aed287.jpg,/imgs/blogs/1/2/4a7b496b-2a08-4af7-aa95-df2c3bd0ef97.jpg,/imgs/blogs/14/3/52b290eb-8b5d-403b-8373-ba0bb856d18e.jpg','提前一周才订到的位置，餐厅在乐堤港的临河一侧，落地窗正对着运河。\n战斧牛排是招牌，三分熟切面很漂亮，配的红酒汁偏酸甜口。\n晚上八点以后灯光会调暗，氛围一下子起来了，适合纪念日。\n人均 300 左右，服务费另算，建议提前订位。',1,4,30,2,42,1,'拱宸桥/上塘',0,'2021-12-28 11:50:01','2026-09-29 08:03:37'),(5,1,2,'人均30💰杭州这家港式茶餐厅我疯狂打call‼️','/imgs/blogs/4/7/863cc302-d150-420d-a596-b16e9232a1a6.jpg,/imgs/blogs/11/12/8b37d208-9414-4e78-b065-9199647bb3e3.jpg,/imgs/blogs/4/1/fa74a6d6-3026-4cb7-b0b6-35abb1e52d11.jpg,/imgs/blogs/9/12/ac2ce2fb-0605-4f14-82cc-c962b8c86688.jpg,/imgs/blogs/4/0/26a7cd7e-6320-432c-a0b4-1b7418f45ec7.jpg,/imgs/blogs/15/9/cea51d9b-ac15-49f6-b9f1-9cf81e9b9c85.jpg','大关这家港式茶餐厅开了十几年，晚上十点还在翻台。\n必点冻柠茶和菠萝油，菠萝油要趁热吃，黄油化开那一下最香。\n干炒牛河锅气很足，牛肉给得也大方。\n人均 30 出头，夜宵档的性价比之王。',3,2,44,1,43,5,'大关',0,'2021-12-28 12:57:49','2026-09-29 08:03:37'),(6,NULL,1,'杭州周末好去处｜💰50就可以骑马啦🐎','/imgs/blogs/blog1.jpg','马场在余杭，市区开车过去四十分钟。\n50 块钱可以骑三圈，教练全程牵着，五岁的小朋友也能上。\n除了骑马还有喂小羊、挖沙池，娃能玩一整个下午。\n建议穿长裤和运动鞋，草地里蚊子有点多。',1,1,30,0,44,6,'余杭',0,'2022-01-11 08:05:47','2026-09-29 08:03:37'),(7,NULL,1,'杭州周末好去处｜沿运河骑行看日落，人少又出片','/imgs/blogs/blog1.jpg','沿着运河绿道从大关骑到拱宸桥，全程大概四十分钟。\n傍晚六点半出发，正好赶上日落，桥上的角度最出片。\n沿途有补给点，骑车累了可以坐下来喝杯东西。\n共享单车就能走，人比西湖边少太多了。',1,0,30,0,45,3,'拱墅区',0,'2022-01-11 08:05:47','2026-09-29 08:04:21'),(23,1,1011,'大关这家茶餐厅，凌晨还在排队｜港式夜宵天花板','/imgs/blogs/6/3/5e9b7bce-4f8b-4fc5-a744-994a82405cd1.png','在 CityHub 刷到这家，当晚就冲了。\n店面不大，晚上十一点门口还坐着等位的人。\n冻柠茶茶味很浓，不齁甜；菠萝油现烤的，酥皮一碰就掉。\n干炒牛河是那种带着锅气的香，牛肉不柴。\n两个人吃了 68，直接封神。',29,4,221,2,49,5,'大关',0,'2026-09-18 08:44:14','2026-09-29 08:03:37'),(24,2,1012,'拱宸桥铜锅涮肉｜人均80吃到扶墙出','/imgs/blogs/10/4/d9b34f21-0b81-4efe-9538-6b1c9516412e.png','老北京铜锅涮羊肉，锅底是清汤配葱姜，最考验肉的品质。\n手切鲜羊肉纹理很清楚，涮八秒就能吃，一点都不膻。\n麻酱是店里自己调的，加一勺韭菜花更香。\n两个人点了三盘肉加一堆配菜，结账 160，性价比很高。',1,1,30,2,38,1,'拱宸桥/上塘',0,'2026-09-19 11:59:12','2026-09-29 08:03:37'),(25,5,1011,'水晶城海底捞｜被服务狠狠拿捏了','/imgs/blogs/15/0/b533dac7-04fc-43e0-bc1e-6a70928b0d73.png','朋友生日来的，进门就被送了长寿面和果盘。\n锅底选了番茄加麻辣，番茄锅煮到最后下面条很绝。\n虾滑现打的很弹，毛肚七上八下刚刚好。\n等位的时候做了美甲，小朋友还有游乐区，确实省心。',0,0,23,0,39,1,'大关',0,'2026-09-19 12:01:11','2026-09-29 08:03:37'),(26,3,1011,'运河上街新白鹿｜人均50的杭帮菜，闭眼冲','/imgs/blogs/12/0/af25d89e-ee37-49c1-b2dc-3ea1a978b91c.png','工作日下午五点半到店，不用等位。\n蛋黄鸡翅是招牌，外脆里嫩，两个人分刚好。\n西湖牛肉羹和糖醋里脊都在线，量比想象中大。\n三个人点了五个菜加主食，一共 156，太适合聚餐了。',0,0,23,0,40,2,'运河上街',0,'2026-09-19 12:10:42','2026-09-29 08:03:37'),(27,4,1011,'乐堤港 Mamala｜适合坐一下午的临河位置','/imgs/blogs/11/0/e9b60fad-01db-4475-a97c-8a58db990522.png','下午两点过来的，人不算多，窗边位置直接坐下。\n手冲是浅烘的果酸调，配一块芝士蛋糕刚好。\n店里很安静，带电脑来办公的人不少，插座也够用。\n坐到五点看运河的夕阳，一整天都很松弛。',0,0,23,0,41,4,'拱宸桥/上塘',0,'2026-09-19 12:11:07','2026-09-29 08:03:37');
/*!40000 ALTER TABLE `tb_blog` ENABLE KEYS */;
