INSERT INTO `tb_blog_comments` VALUES (1,1011,4,0,0,'这家我也去过！环境很安静，适合坐着发呆一下午。',NULL,6,0,'2026-09-29 07:24:31','2026-09-29 07:24:31'),(2,1012,4,0,0,'请问周末去要排队吗？',NULL,3,0,'2026-09-29 07:24:31','2026-09-29 07:24:31'),(3,1013,4,0,0,'拍照超出片，随手一拍都是壁纸。','/imgs/types/jd.png',9,0,'2026-09-29 07:24:31','2026-09-29 07:24:31'),(4,1,4,2,2,'要的，建议下午三点前去，人会少一些。',NULL,2,0,'2026-09-29 07:24:31','2026-09-29 07:24:31'),(5,1011,5,0,0,'价格很实在，分量也足，回购第三次了。',NULL,5,0,'2026-09-29 07:24:31','2026-09-29 07:24:31'),(6,1012,5,0,0,'老板人很nice，还送了小菜。',NULL,4,0,'2026-09-29 07:24:31','2026-09-29 07:24:31'),(7,1013,6,0,0,'位置有点隐蔽，跟着导航走还是很好找的。',NULL,1,0,'2026-09-29 07:24:31','2026-09-29 07:24:31'),(8,1011,23,0,0,'写得太好了，周末就去打卡！',NULL,12,0,'2026-09-29 07:24:31','2026-09-29 07:24:31'),(9,1012,23,0,0,'这个角度拍得真好看，求机位。',NULL,7,0,'2026-09-29 07:24:31','2026-09-29 07:24:31'),(10,1013,23,9,9,'就在门口左手边，逆光拍最好看。',NULL,3,0,'2026-09-29 07:24:31','2026-09-29 07:24:31'),(11,1,23,0,0,'感谢分享，已经收藏了。',NULL,5,0,'2026-09-29 07:24:31','2026-09-29 07:24:31'),(12,1012,24,0,0,'性价比之王，学生党友好。',NULL,8,0,'2026-09-29 07:24:31','2026-09-29 07:24:31');
