/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_topic` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '话题名称，不含 #',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '话题简介',
  `cover` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '话题封面图',
  `blog_count` int unsigned NOT NULL DEFAULT '0' COMMENT '关联笔记数',
  `view_count` int unsigned NOT NULL DEFAULT '0' COMMENT '话题浏览量',
  `sort` int unsigned NOT NULL DEFAULT '0' COMMENT '排序，越小越靠前',
  `status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '状态 0:正常 1:下线',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_topic_name` (`name`),
  KEY `idx_topic_sort` (`sort`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='话题表';
